parameters.jsCode:
// Судья вернул оценки — приводим каждую к форме строки eval_log и подшиваем к своему диалогу.
//
// 🔴 Прогон 2013: узел брал $input.first() и писал в журнал ОДНУ оценку из 16.
// Судья честно отработал все 16 диалогов за 10 минут, а в eval_log ушла бы первая строка —
// и метрики качества считались бы по одному диалогу. Порядок элементов цепь LLM сохраняет,
// поэтому i-я оценка относится к i-му диалогу.
const src = $('1. Postgres — выборка 20 диалогов').all();
const clamp = (x) => Math.max(0, Math.min(10, Math.round(Number(x) || 0)));

return $input.all().map((it, i) => {
  const s = (src[i] || src[0]).json;
  const v = it.json.output || it.json;
  return { json: {
    operation_id: s.operation_id,
    input: s.user_message_masked,
    output: s.reply_masked,
    intent_predicted: s.intent,
    accuracy: clamp(v.accuracy),
    completeness: clamp(v.completeness),
    tone: clamp(v.tone),
    issues: Array.isArray(v.issues) ? v.issues.join('; ') : (v.issues || null),
    // Фиксируем модель судьи прямо в журнале: доказательство, что оценивал не тот,
    // кто отвечал. Урок Модуля 13.
    judge_model: 'meta/muse-glimmer (локально)',
  } };
});

// Пороги из брифа: средний балл ниже 7 или доля эскалаций выше 20 % — тревога.
// Точность роутера считается по данным escalations: оператор при разборе проставляет
// фактический интент, и метрика получается на реальных данных, а не на самооценке модели.
const m = $input.first().json || {};
const AVG_MIN = 7.0, ESC_MAX = 20.0, ROUTER_MIN = 85.0;

const problems = [];
if (m.avg_total !== null && Number(m.avg_total) < AVG_MIN)
  problems.push(`средний балл ${m.avg_total} ниже ${AVG_MIN}`);
if (m.escalation_pct !== null && Number(m.escalation_pct) > ESC_MAX)
  problems.push(`доля эскалаций ${m.escalation_pct} % выше ${ESC_MAX} %`);
if (m.router_accuracy_pct !== null && Number(m.router_accuracy_pct) < ROUTER_MIN)
  problems.push(`точность роутера ${m.router_accuracy_pct} % ниже ${ROUTER_MIN} %`);

const routerLine = Number(m.router_sample) > 0
  ? `${m.router_accuracy_pct} % (по ${m.router_sample} разобранным эскалациям)`
  : 'не измерена — оператор ещё не проставил ни одного фактического интента';

const text =
  `🧪 *Eval за сутки*\n\n` +
  `Оценено диалогов: ${m.judged || 0}\n` +
  `Точность: ${m.avg_accuracy ?? '—'} · полнота: ${m.avg_completeness ?? '—'} · тон: ${m.avg_tone ?? '—'}\n` +
  `Средний балл: *${m.avg_total ?? '—'}*\n\n` +
  `Обращений за сутки: ${m.ops_24h || 0}\n` +
  `Эскалаций: ${m.escalation_pct ?? '—'} % · из кэша: ${m.cache_pct ?? '—'} %\n` +
  `Точность роутера: ${routerLine}\n\n` +
  (problems.length ? `⚠️ *Требует внимания:*\n— ${problems.join('\n— ')}` : '✅ Пороги в норме.');

return [{ json: { ...m, alert: problems.length > 0, problems, report_text: text } }];
